/**
 * Create a new presentation with all masters pre-registered.
 * @param {string} [title] - Presentation title
 * @returns {Promise<PptxGenJS>} Configured PptxGenJS instance
 */
export async function createPresentation(title = '') {
  const { default: PptxGenJS } = await import('pptxgenjs');
  const pptx = new PptxGenJS();
  pptx.defineLayout({ name: 'LAYOUT_CUSTOM', width: 26.6667, height: 15 });
  pptx.layout = 'LAYOUT_CUSTOM';
  if (title) pptx.title = title;
  registerMasters(pptx);
  return pptx;
}

